class DiscoverScreen extends ConsumerStatefulWidget{const DiscoverScreen({super.key});@override ConsumerState<DiscoverScreen> createState()=>_DiscoverScreenState();}
class _DiscoverScreenState extends ConsumerState<DiscoverScreen>{final search=TextEditingController();String species='All';static const guides=[('Getting started','Practical first steps for a new dog or cat.'),('Feeding basics','Record meals and discuss diet changes with a veterinarian.'),('Grooming','Gentle, positive grooming routines.'),('Positive-reinforcement training','Reward-based learning and short practice sessions.'),('Enrichment','Safe play and enrichment ideas.'),('Travel and seasonal safety','Prepare for changing environments.'),('Senior pet comfort','Home comfort ideas for older pets.'),('Adoption transition','A calm checklist for bringing a pet home.')];@override void dispose(){search.dispose();super.dispose();}
@override Widget build(BuildContext context,WidgetRef ref){final q=search.text.toLowerCase();final items=guides.where((g)=>g.$1.toLowerCase().contains(q)||g.$2.toLowerCase().contains(q)).toList();return ListView(padding:const EdgeInsets.all(18),children:[Text('Discover',style:Theme.of(context).textTheme.headlineMedium),const SizedBox(height:6),const Text('Helpful, practical ideas for everyday pet care.'),const SizedBox(height:14),TextField(controller:search,onChanged:(_)=>setState((){}),decoration:const InputDecoration(prefixIcon:Icon(Icons.search),hintText:'Search guides and topics')),const SizedBox(height:12),Wrap(spacing:8,children:['All','Dog','Cat'].map((v)=>ChoiceChip(label:Text(v),selected:species==v,onSelected:(_)=>setState(()=>species=v))).toList()),const SizedBox(height:14),const DisclaimerCard('Educational information is not veterinary advice. Health and urgent safety content should be reviewed by qualified professionals.'),const SizedBox(height:16),...items.map((g)=>Card(child:ListTile(leading:const Icon(Icons.menu_book_outlined,color:Color(0xFF39845A)),title:Text(g.$1,style:const TextStyle(fontWeight:FontWeight.w800)),subtitle:Text(g.$2),trailing:const Icon(Icons.chevron_right),onTap:()=>showModalBottomSheet(context:context,builder:(d)=>Padding(padding:const EdgeInsets.all(22),child:Column(mainAxisSize:MainAxisSize.min,crossAxisAlignment:CrossAxisAlignment.start,children:[Text(g.$1,style:Theme.of(context).textTheme.titleLarge),const SizedBox(height:12),Text(g.$2),const SizedBox(height:12),const Text('Build gentle, repeatable routines and adapt them to the individual animal. Ask your veterinarian about health concerns.'),TextButton(onPressed:()=>Navigator.pop(d),child:const Text('Close'))]))))),const SizedBox(height:12),OutlinedButton.icon(onPressed:()=>Navigator.push(context,MaterialPageRoute(builder:(_)=>const ChecklistsScreen())),icon:const Icon(Icons.checklist),label:const Text('Browse care checklists'))]);}}
